var placeholder=null,modal=null,form=null;
function css(){if(document.getElementById('bc164-css'))return;var s=document.createElement('style');s.id='bc164-css';s.textContent='.bc164-overlay{position:fixed;inset:0;background:rgba(6,14,11,.82);z-index:9300;display:flex;align-items:flex-start;justify-content:center;padding:18px;overflow:auto}.bc164-modal{width:min(900px,100%);margin:28px auto;background:var(--stone);border:1px solid rgba(212,176,92,.35);border-radius:14px;box-shadow:0 24px 70px rgba(0,0,0,.58);padding:18px}.bc164-head{display:flex;justify-content:space-between;align-items:center;gap:12px;margin-bottom:12px}.bc164-head h3{margin:0;color:var(--gold)}.bc164-close{background:none;border:0;color:var(--mist);font-size:24px;cursor:pointer}.bc164-tools{display:flex;flex-wrap:wrap;gap:8px;padding:10px 0 14px;border-bottom:1px solid rgba(212,176,92,.16);margin-bottom:14px}.bc164-tools button{padding:9px 12px;border-radius:8px;border:1px solid rgba(212,176,92,.28);background:rgba(212,176,92,.09);color:var(--text);cursor:pointer;font-size:12.5px;font-weight:600}.bc164-tools button:hover{border-color:var(--gold);color:var(--gold-bright)}.bc164-foot{display:flex;justify-content:flex-end;gap:8px;margin-top:14px}.bc164-foot button{padding:10px 15px;border-radius:8px}.bc164-save{background:rgba(212,176,92,.16);border:1px solid rgba(212,176,92,.35);color:var(--text);font-weight:700}.bc164-cancel{background:transparent;border:1px solid rgba(212,176,92,.2);color:var(--mist)}#tab-productos #bc164-add-open{margin:0 0 12px;padding:10px 15px;border-radius:8px;border:1px solid rgba(212,176,92,.35);background:rgba(212,176,92,.12);color:var(--text);font-weight:700;cursor:pointer}.bc164-native-hidden{display:none!important}';document.head.appendChild(s)}
